CREATE TABLE orders (
	number VARCHAR(20) NOT NULL, 
	user_id CHAR(36) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	payment_method VARCHAR(8) NOT NULL, 
	payment_status VARCHAR(20) NOT NULL, 
	ship_to JSON NOT NULL, 
	items_total BIGINT NOT NULL, 
	shipping_total BIGINT NOT NULL, 
	cod_fee BIGINT NOT NULL, 
	discount_total BIGINT NOT NULL DEFAULT 0, 
	coupon_code VARCHAR(30) NOT NULL DEFAULT '', 
	fees JSON NOT NULL DEFAULT (CAST('[]' AS JSON)), 
	fees_total BIGINT NOT NULL DEFAULT 0, 
	tip_paise BIGINT NOT NULL DEFAULT 0, 
	buyer_gstin VARCHAR(15) NOT NULL DEFAULT '', 
	fee_invoice_number VARCHAR(16) NOT NULL DEFAULT '', 
	fee_invoice_date DATETIME(6), 
	buyer_business VARCHAR(160) NOT NULL DEFAULT '', 
	grand_total BIGINT NOT NULL, 
	currency VARCHAR(3) NOT NULL DEFAULT 'INR', 
	fx_rate NUMERIC(20, 10) NOT NULL DEFAULT 1, 
	refunded_total BIGINT NOT NULL, 
	idempotency_key VARCHAR(64) NOT NULL, 
	payment_expires_at DATETIME(6), 
	placed_at DATETIME(6), 
	cancelled_at DATETIME(6), 
	id CHAR(36) NOT NULL, 
	created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), 
	updated_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), 
	CONSTRAINT pk_orders PRIMARY KEY (id), 
	CONSTRAINT uq_orders_user_idempotency UNIQUE (user_id, idempotency_key), 
	CONSTRAINT ck_orders_status CHECK (status IN ('pending_payment','placed','cancelled')), 
	CONSTRAINT ck_orders_payment_method CHECK (payment_method IN ('cod','online')), 
	CONSTRAINT ck_orders_payment_status CHECK (payment_status IN ('pending','paid','cod','failed','refunded','partially_refunded')), 
	CONSTRAINT ck_orders_totals CHECK (grand_total = items_total + shipping_total + cod_fee + fees_total + tip_paise - discount_total), 
	CONSTRAINT ck_orders_fees CHECK (fees_total >= 0 AND tip_paise >= 0), 
	CONSTRAINT uq_orders_number UNIQUE (number), 
	CONSTRAINT fk_orders_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE INDEX ix_orders_status ON orders (status);
CREATE INDEX ix_orders_user_id ON orders (user_id);

