	status VARCHAR(16) NOT NULL, 
	items_total BIGINT NOT NULL, 
	shipping_fee BIGINT NOT NULL, 
	cod_fee BIGINT NOT NULL, 
	seller_discount BIGINT NOT NULL DEFAULT 0, 
	platform_discount BIGINT NOT NULL DEFAULT 0, 
	total BIGINT NOT NULL, 
	taxable_total BIGINT NOT NULL, 
	shipping_gst_bps INTEGER NOT NULL, 
	is_interstate TINYINT(1) NOT NULL, 
	commission_paise BIGINT NOT NULL, 
	commission_gst_paise BIGINT NOT NULL, 
	tcs_paise BIGINT NOT NULL, 
	tds_paise BIGINT NOT NULL, 
	seller_payout_paise BIGINT NOT NULL, 
	settlement_due_at DATETIME(6), 
	settlement_status VARCHAR(10) NOT NULL, 
	warehouse_id CHAR(36), 
	invoice_number VARCHAR(20) NOT NULL DEFAULT '', 
	invoice_date DATETIME(6), 
	shipping_provider VARCHAR(12) NOT NULL DEFAULT 'manual', 
	provider_order_id VARCHAR(40) NOT NULL DEFAULT '', 
	provider_shipment_id VARCHAR(40) NOT NULL DEFAULT '', 
	label_url VARCHAR(400) NOT NULL DEFAULT '', 
	expected_delivery_at DATETIME(6), 
	returned_total BIGINT NOT NULL DEFAULT 0, 
	courier_name VARCHAR(60) NOT NULL, 
	tracking_number VARCHAR(60) NOT NULL, 
	tracking_url VARCHAR(400) NOT NULL, 
	confirmed_at DATETIME(6), 
	packed_at DATETIME(6), 
	shipped_at DATETIME(6), 
	delivered_at DATETIME(6), 
	cancelled_at DATETIME(6), 
	cancelled_by VARCHAR(10) NOT NULL, 
	cancel_reason VARCHAR(300) NOT NULL, 
	ready_for_pickup_at DATETIME(6), 
	pickup_code VARCHAR(6) NOT NULL DEFAULT '', 
	delivery_otp VARCHAR(6) NOT NULL DEFAULT '', 
	delivery_zone_id CHAR(36), 
	fleet_alerted_at DATETIME(6), 
	id CHAR(36) NOT NULL, 
	created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), 
	updated_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), 
	CONSTRAINT pk_sub_orders PRIMARY KEY (id), 
	CONSTRAINT ck_sub_orders_status CHECK (status IN ('pending_payment','placed','confirmed','packed','shipped','delivered','cancelled')), 
	CONSTRAINT ck_sub_orders_settlement_status CHECK (settlement_status IN ('not_due','pending','eligible','paid','void')), 
	CONSTRAINT ck_sub_orders_totals CHECK (total = items_total + shipping_fee + cod_fee - seller_discount), 
	CONSTRAINT fk_sub_orders_order_id_orders FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	CONSTRAINT fk_sub_orders_seller_id_sellers FOREIGN KEY(seller_id) REFERENCES sellers (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_sub_orders_number UNIQUE (number), 
	CONSTRAINT fk_sub_orders_warehouse_id_warehouses FOREIGN KEY(warehouse_id) REFERENCES warehouses (id) ON DELETE SET NULL, 
	CONSTRAINT fk_sub_orders_delivery_zone_id_delivery_zones FOREIGN KEY(delivery_zone_id) REFERENCES delivery_zones (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
