CREATE TABLE order_items (
	sub_order_id CHAR(36) NOT NULL, 
	product_id CHAR(36) NOT NULL, 
	variant_id CHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	variant_label VARCHAR(200) NOT NULL, 
	image_url VARCHAR(400) NOT NULL, 
	sku VARCHAR(60) NOT NULL, 
	hsn_code VARCHAR(8) NOT NULL, 
	qty INTEGER NOT NULL, 
	unit_price BIGINT NOT NULL, 
	unit_mrp BIGINT NOT NULL, 
	line_total BIGINT NOT NULL, 
	gst_bps INTEGER NOT NULL, 
	taxable_value BIGINT NOT NULL, 
	cgst BIGINT NOT NULL, 
	sgst BIGINT NOT NULL, 
	igst BIGINT NOT NULL, 
	commission_bps INTEGER NOT NULL, 
	commission_paise BIGINT NOT NULL, 
	seller_discount BIGINT NOT NULL DEFAULT 0, 
	platform_discount BIGINT NOT NULL DEFAULT 0, 
	returned_qty INTEGER NOT NULL DEFAULT 0, 
	return_window_days INTEGER NOT NULL DEFAULT 0, 
	id CHAR(36) NOT NULL, 
	CONSTRAINT pk_order_items PRIMARY KEY (id), 
	CONSTRAINT ck_order_items_qty CHECK (qty > 0), 
	CONSTRAINT ck_order_items_line_total CHECK (line_total = unit_price * qty), 
	CONSTRAINT ck_order_items_tax_split CHECK (taxable_value + cgst + sgst + igst = line_total - seller_discount), 
	CONSTRAINT ck_order_items_returned_qty CHECK (returned_qty BETWEEN 0 AND qty), 
	CONSTRAINT fk_order_items_sub_order_id_sub_orders FOREIGN KEY(sub_order_id) REFERENCES sub_orders (id) ON DELETE CASCADE, 
	CONSTRAINT fk_order_items_product_id_products FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_order_items_variant_id_variants FOREIGN KEY(variant_id) REFERENCES variants (id) ON DELETE RESTRICT
