	CONSTRAINT fk_stock_movements_warehouse_id_warehouses FOREIGN KEY(warehouse_id) REFERENCES warehouses (id) ON DELETE CASCADE, 
	CONSTRAINT fk_stock_movements_actor_user_id_users FOREIGN KEY(actor_user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE INDEX ix_stock_movements_created_at ON stock_movements (created_at);
CREATE INDEX ix_stock_movements_variant_id ON stock_movements (variant_id);

CREATE TABLE answer_reports (
	answer_id CHAR(36) NOT NULL, 
