	created_at DATETIME(6) NOT NULL, 
	CONSTRAINT pk_answer_reports PRIMARY KEY (answer_id, user_id), 
	CONSTRAINT fk_answer_reports_answer_id_product_answers FOREIGN KEY(answer_id) REFERENCES product_answers (id) ON DELETE CASCADE, 
	CONSTRAINT fk_answer_reports_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE answer_votes (
	answer_id CHAR(36) NOT NULL, 
	user_id CHAR(36) NOT NULL, 
	created_at DATETIME(6) NOT NULL, 
	CONSTRAINT pk_answer_votes PRIMARY KEY (answer_id, user_id), 
	CONSTRAINT fk_answer_votes_answer_id_product_answers FOREIGN KEY(answer_id) REFERENCES product_answers (id) ON DELETE CASCADE, 
