) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE delivery_assignments (
	order_id CHAR(36) NOT NULL, 
	sub_order_id CHAR(36) NOT NULL, 
	delivery_boy_id CHAR(36) NOT NULL, 
	assigned_by CHAR(36), 
	mode VARCHAR(6) NOT NULL, 
	kind VARCHAR(8) NOT NULL DEFAULT 'delivery', 
	return_id CHAR(36), 
	status VARCHAR(10) NOT NULL, 
	reject_reason VARCHAR(200) NOT NULL, 
	assigned_at DATETIME(6) NOT NULL, 
	expires_at DATETIME(6), 
	accepted_at DATETIME(6), 
	at_store_at DATETIME(6), 
	picked_at DATETIME(6), 
	on_the_way_at DATETIME(6), 
	reached_at DATETIME(6), 
	delivered_at DATETIME(6), 
	ended_at DATETIME(6), 
	status_at DATETIME(6) NOT NULL, 
	stuck_alerted_at DATETIME(6), 
	cod_amount BIGINT NOT NULL, 
	cod_collected BIGINT NOT NULL, 
	cod_method VARCHAR(6) NOT NULL, 
	proof_photo VARCHAR(300) NOT NULL, 
	picked_lat NUMERIC(9, 6), 
	picked_lng NUMERIC(9, 6), 
	drop_lat NUMERIC(9, 6), 
	drop_lng NUMERIC(9, 6), 
	distance_km NUMERIC(7, 2), 
	fee_paise BIGINT NOT NULL, 
	tip_paise BIGINT NOT NULL DEFAULT 0, 
	bonus_paise BIGINT NOT NULL DEFAULT 0, 
	payout_id CHAR(36), 
	fail_reason VARCHAR(200) NOT NULL, 
	rating SMALLINT, 
	rating_comment TEXT NOT NULL, 
	rated_at DATETIME(6), 
	created_at DATETIME(6) NOT NULL, 
	id CHAR(36) NOT NULL, 
	CONSTRAINT pk_delivery_assignments PRIMARY KEY (id), 
	CONSTRAINT ck_delivery_assignments_status CHECK (status IN ('offered', 'accepted', 'at_store', 'picked', 'on_the_way', 'reached', 'delivered', 'rejected', 'expired', 'cancelled', 'failed')), 
	CONSTRAINT ck_delivery_assignments_mode CHECK (mode IN ('manual','auto')), 
	CONSTRAINT ck_delivery_assignments_kind CHECK (kind IN ('delivery','return','pickup')), 
	CONSTRAINT ck_delivery_assignments_rating CHECK (rating IS NULL OR rating BETWEEN 1 AND 5), 
	CONSTRAINT ck_delivery_assignments_money CHECK (cod_collected >= 0 AND cod_amount >= 0 AND fee_paise >= 0 AND bonus_paise >= 0), 
	CONSTRAINT fk_delivery_assignments_order_id_orders FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	CONSTRAINT fk_delivery_assignments_sub_order_id_sub_orders FOREIGN KEY(sub_order_id) REFERENCES sub_orders (id) ON DELETE CASCADE, 
	CONSTRAINT fk_delivery_assignments_delivery_boy_id_delivery_boys FOREIGN KEY(delivery_boy_id) REFERENCES delivery_boys (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_delivery_assignments_assigned_by_users FOREIGN KEY(assigned_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_delivery_assignments_return_id_return_requests FOREIGN KEY(return_id) REFERENCES return_requests (id) ON DELETE SET NULL, 
	CONSTRAINT fk_delivery_assignments_payout_id_delivery_payouts FOREIGN KEY(payout_id) REFERENCES delivery_payouts (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE INDEX ix_delivery_assignments_boy_status ON delivery_assignments (delivery_boy_id, status);
CREATE INDEX ix_delivery_assignments_delivery_boy_id ON delivery_assignments (delivery_boy_id);
CREATE INDEX ix_delivery_assignments_order_id ON delivery_assignments (order_id);
CREATE INDEX ix_delivery_assignments_payout_id ON delivery_assignments (payout_id);
CREATE INDEX ix_delivery_assignments_return_id ON delivery_assignments (return_id);
CREATE INDEX ix_delivery_assignments_status ON delivery_assignments (status);
CREATE INDEX ix_delivery_assignments_sub_order_id ON delivery_assignments (sub_order_id);

CREATE TABLE return_items (
	return_id CHAR(36) NOT NULL, 
	order_item_id CHAR(36) NOT NULL, 
	qty INTEGER NOT NULL, 
	amount BIGINT NOT NULL, 
	`condition` VARCHAR(10) NOT NULL DEFAULT '', 
	id CHAR(36) NOT NULL, 
	CONSTRAINT pk_return_items PRIMARY KEY (id), 
	CONSTRAINT ck_return_items_qty CHECK (qty > 0), 
	CONSTRAINT ck_return_items_condition CHECK (`condition` IN ('','sellable','damaged')), 
	CONSTRAINT uq_return_items_return_order_item UNIQUE (return_id, order_item_id), 
	CONSTRAINT fk_return_items_return_id_return_requests FOREIGN KEY(return_id) REFERENCES return_requests (id) ON DELETE CASCADE, 
	CONSTRAINT fk_return_items_order_item_id_order_items FOREIGN KEY(order_item_id) REFERENCES order_items (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE INDEX ix_return_items_return_id ON return_items (return_id);

CREATE TABLE review_reports (
