) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE INDEX ix_seller_ledger_available_at ON seller_ledger (available_at);
CREATE INDEX ix_seller_ledger_payout_id ON seller_ledger (payout_id);
CREATE INDEX ix_seller_ledger_seller_id ON seller_ledger (seller_id);

CREATE TABLE delivery_complaints (
