-- product search (PostgreSQL tsvector + trigram in the reference version)
CREATE FULLTEXT INDEX ft_products_search ON products (title, brand, description);
-- one live offer or trip per package at a time (a partial unique index in PostgreSQL)
ALTER TABLE delivery_assignments ADD COLUMN active_sub_order_id CHAR(36) AS (CASE WHEN status IN ('offered','accepted','at_store','picked','on_the_way','reached') THEN sub_order_id END) VIRTUAL;
CREATE UNIQUE INDEX uq_delivery_assignments_active ON delivery_assignments (active_sub_order_id);

SET FOREIGN_KEY_CHECKS = 1;
